    private static void network(GameTestHelper h,MachineKind kind){h.setBlock(1,1,1,AWCells.BLOCKS.get(kind).get());h.setBlock(2,1,1,AEBlocks.DRIVE.block());h.setBlock(2,0,1,AEBlocks.CREATIVE_ENERGY_CELL.block());var drive=(DriveBlockEntity)h.getBlockEntity(new BlockPos(2,1,1));drive.getInternalInventory().setItemDirect(0,AEItems.ITEM_CELL_64K.stack());drive.getInternalInventory().setItemDirect(1,AEItems.FLUID_CELL_64K.stack());h.runAfterDelay(25,()->{var main=machine(h);for(var pos:List.of(new BlockPos(2,1,1),new BlockPos(2,0,1))){var b=(appeng.me.helpers.IGridConnectedBlockEntity)h.getBlockEntity(pos);if(main.getMainNode().getGrid()!=b.getMainNode().getGrid())GridHelper.createConnection(main.getMainNode().getNode(),b.getMainNode().getNode());}});}
    private static CellsBlockEntity machine(GameTestHelper h){return (CellsBlockEntity)h.getBlockEntity(new BlockPos(1,1,1));}
    @GameTest(template="empty") public static void allTierRecipesCellHandlersAndLongAccounting(GameTestHelper h){
        h.assertTrue(AWCells.CELLS.size()==48&&AWCells.COMPONENTS.size()==45&&AWCells.PARTS.size()==10&&AWCells.BLOCKS.size()==9&&AWCells.MATERIALS.size()==22,"Complete registry matrix");
        for(var entry:AWCells.CELLS.values()){
            var stack=new ItemStack(entry.get());var item=entry.get();h.assertTrue(stack.getMaxStackSize()==1&&StorageCells.isCellHandled(stack),"Stack limit and handler "+entry.getId());
            if(item.family.creative()){item.getConfigInventory(stack).setStack(0,new GenericStack(item.family.fluid?WATER:IRON,1));var state=CellHandler.open(stack,null);h.assertTrue(state.extract(item.family.fluid?WATER:IRON,1L<<42,Actionable.MODULATE,SOURCE)==1L<<42,"Creative long extraction");continue;}
            if(item.family==CellFamily.CONFIGURABLE)continue;
            boolean recipe=h.getLevel().getRecipeManager().getRecipes().stream().anyMatch(r->r.getResultItem(h.getLevel().registryAccess()).is(item));h.assertTrue(recipe,"Survival cell recipe "+entry.getId());
            var state=StorageCells.getCellInventory(stack,null);var key=item.family.fluid?WATER:IRON;long requested=item.family.highDensity?1L<<33:81;var before=stack.copy();h.assertTrue(state.insert(key,requested,Actionable.SIMULATE,SOURCE)==requested,"Simulation capacity "+entry.getId());h.assertTrue(ItemStack.matches(before,stack),"Simulation leaves NBT unchanged");
            h.assertTrue(state.insert(key,requested,Actionable.MODULATE,SOURCE)==requested,"Insert "+entry.getId());state.persist();var reopened=StorageCells.getCellInventory(stack.copy(),null);h.assertTrue(reopened.extract(key,requested,Actionable.MODULATE,SOURCE)==requested,"Exact persisted extraction "+entry.getId());
        }
        for(var recipe:h.getLevel().getRecipeManager().getRecipes())if(recipe.getId().getNamespace().equals("aedialsworks"))
            for(var ingredient:recipe.getIngredients())if(!ingredient.isEmpty())h.assertTrue(ingredient.getItems().length>0,"Resolvable recipe ingredient "+recipe.getId());
        h.succeed();
    }
    @GameTest(template="empty") public static void partitionCompactionUpgradeAndRemainderConservation(GameTestHelper h){
        var stack=new ItemStack(AWCells.cell(CellFamily.COMPACTING,CellTier.K1).get());var item=(TieredCellItem)stack.getItem();item.getConfigInventory(stack).setStack(0,new GenericStack(IRON,1));
        var cell=(CompactingCellState)CellHandler.open(stack,null);h.assertTrue(cell.chain()==null,"Unbound empty pool");h.assertTrue(cell.insert(AEItemKey.of(Items.IRON_BLOCK),11,Actionable.MODULATE,SOURCE)==11,"Actual 3x3 reversible recipe");h.assertTrue(cell.extract(IRON,98,Actionable.MODULATE,SOURCE)==98,"Decompress exactly");h.assertTrue(cell.extract(AEItemKey.of(Items.IRON_NUGGET),9,Actionable.MODULATE,SOURCE)==9&&cell.storedUnits()==0,"Residual low denomination preserved");
        h.assertTrue(cell.insert(AEItemKey.of(Items.DIRT),1,Actionable.MODULATE,SOURCE)==0,"Partition rejects unrelated item");cell.insert(IRON,9,Actionable.MODULATE,SOURCE);item.getConfigInventory(stack).setStack(0,new GenericStack(AEItemKey.of(Items.GOLD_INGOT),1));cell= (CompactingCellState)CellHandler.open(stack,null);h.assertTrue(cell.insert(IRON,1,Actionable.MODULATE,SOURCE)==0&&cell.extract(IRON,9,Actionable.MODULATE,SOURCE)==9,"Repartition blocks new input but preserves recovery");
        var dense=new ItemStack(AWCells.cell(CellFamily.HD_ITEM,CellTier.K1).get());var d=(TieredCellItem)dense.getItem();d.getConfigInventory(dense).setStack(0,new GenericStack(IRON,1));var state=CellHandler.open(dense,null);h.assertTrue(state.insert(AEItemKey.of(Items.DIRT),100,Actionable.SIMULATE,SOURCE)==0,"Dense partition");d.getUpgrades(dense).setItemDirect(0,AEItems.INVERTER_CARD.stack());state=CellHandler.open(dense,null);h.assertTrue(state.insert(IRON,1,Actionable.SIMULATE,SOURCE)==0&&state.insert(AEItemKey.of(Items.DIRT),1,Actionable.SIMULATE,SOURCE)==1,"Inverse card");h.succeed();
    }
    @GameTest(template="empty") public static void componentSwapAssemblyAndRecipeTypes(GameTestHelper h){
        var blank=new ItemStack(AWCells.CELLS.get("configurable_cell").get());var component=new ItemStack(AWCells.component(CellFamily.HD_FLUID,CellTier.K1).get());var fluid=CellComponentRecipe.replaced(blank,component);h.assertTrue(!fluid.isEmpty(),"Configurable assembly");var state=CellHandler.open(fluid,null);h.assertTrue(state.insert(WATER,1L<<34,Actionable.MODULATE,SOURCE)==1L<<34,"Component selects fluid and long capacity");
        var expanded=CellComponentRecipe.replaced(fluid,new ItemStack(AWCells.component(CellFamily.HD_FLUID,CellTier.K4).get()));h.assertTrue(!expanded.isEmpty()&&count(CellHandler.open(expanded,null),WATER)==1L<<34,"Filled component swap preserves contents");h.assertTrue(CellComponentRecipe.replaced(fluid,new ItemStack(AWCells.component(CellFamily.HD_ITEM,CellTier.K4).get())).isEmpty(),"Channel-changing swap rejected when filled");
        var huge=new ItemStack(AWCells.cell(CellFamily.HD_ITEM,CellTier.G1).get());CellHandler.open(huge,null).insert(IRON,1L<<55,Actionable.MODULATE,SOURCE);h.assertTrue(CellComponentRecipe.replaced(huge,new ItemStack(AWCells.component(CellFamily.HD_ITEM,CellTier.K1).get())).isEmpty(),"Unsafe shrink rejected");
        long inscriber=h.getLevel().getRecipeManager().getRecipes().stream().filter(x->x.getId().getNamespace().equals("aedialsworks")&&x.getId().getPath().startsWith("cells/inscriber/")).count();h.assertTrue(inscriber==6,"Six real inscriber recipes loaded");h.succeed();
    }
    private static void interfaceTest(GameTestHelper h,MachineKind kind){network(h,kind);final CellsPart[] part={null};
        h.runAfterDelay(30,()->{part[0]=PartHelper.setPart(h.getLevel(),h.absolutePos(new BlockPos(1,1,3)),Direction.NORTH,h.makeMockPlayer(),AWCells.PARTS.get(kind).get());});
        h.runAfterDelay(55,()->{GridHelper.createConnection(machine(h).getMainNode().getNode(),part[0].getGridNode());});
        h.runAfterDelay(80,()->{var storage=machine(h).getMainNode().getGrid().getStorageService().getInventory();storage.insert(IRON,10000,Actionable.MODULATE,SOURCE);storage.insert(WATER,100000,Actionable.MODULATE,SOURCE);
            for(CellsHost host:List.of(machine(h),part[0])){var logic=(InterfaceLogic)host.cellsLogic();for(int u=0;u<4;u++)logic.upgrades.setItemDirect(u,AEItems.CAPACITY_CARD.stack());h.assertTrue(logic.pages()==5,"Capacity cards open all five pages");
                for(var port:logic.ports){AEKey key=port.fluid?WATER:IRON;port.filters[179]=key;port.limits[179]=port.fluid?4000:32;if(!port.output)h.assertTrue(port.insert(179,key,port.fluid?2000:16,false,false)>0,"Last-page import buffer");}
            }});
        h.runAfterDelay(145,()->{for(CellsHost host:List.of(machine(h),part[0])){var logic=(InterfaceLogic)host.cellsLogic();h.assertTrue(logic.active(),"Real grid active");for(var port:logic.ports)h.assertTrue(port.amounts[179]==(port.output?(port.fluid?4000:32):0),"Polling last page "+kind+" "+port.fluid+" "+port.output);
            var saved=logic.save();var copy=AWCells.PARTS.get(kind).get().createPart();copy.logic.load(saved);for(int i=0;i<logic.ports.size();i++)h.assertTrue(((InterfaceLogic)copy.logic).ports.get(i).amounts[179]==logic.ports.get(i).amounts[179],"Buffers reload exactly");
            var card=logic.exportData(appeng.util.SettingsFrom.MEMORY_CARD);h.assertFalse(card.contains("buffers")||card.contains("upgrades"),"Settings cannot duplicate inventory");
        }h.succeed();});
    }
