    @GameTest(template="empty") public static void bucketMenuTransferAndMachineConversionPreservePayload(GameTestHelper h){
        h.setBlock(1,1,1,AWCells.BLOCKS.get(MachineKind.FLUID_IMPORT).get());var logic=(InterfaceLogic)machine(h).cellsLogic();var player=net.minecraftforge.common.util.FakePlayerFactory.get(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"P3Buckets"));player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);var pos=machine(h).cellsPos();player.setPos(pos.getX(),pos.getY(),pos.getZ());var nonce=UUID.randomUUID();var menu=new com.mpp.aedialsworks.cells.menu.CellsMenu(83,player.getInventory(),machine(h),nonce);player.containerMenu=menu;var action=new CompoundTag();action.putUUID("session",nonce);action.putInt("port",0);action.putInt("slot",0);menu.setCarried(new ItemStack(Items.WATER_BUCKET));menu.receiveClientAction(player,com.mpp.aedialsworks.common.util.AWIds.id("cells_buffer"),action);h.assertTrue(menu.getCarried().is(Items.BUCKET)&&logic.ports.get(0).amounts[0]==1000,"Bucket deposits 1000 mB: valid="+menu.stillValid(player)+" build="+player.mayBuild()+" amount="+logic.ports.get(0).amounts[0]+" cursor="+menu.getCarried());menu.receiveClientAction(player,com.mpp.aedialsworks.common.util.AWIds.id("cells_buffer"),action);h.assertTrue(menu.getCarried().is(Items.WATER_BUCKET)&&logic.ports.get(0).amounts[0]==0,"Bucket withdraws exactly 1000 mB");player.containerMenu=player.inventoryMenu;
        var payload=new CompoundTag();payload.put("cells",logic.save());var input=new ItemStack(AWCells.BLOCK_ITEMS.get(MachineKind.FLUID_IMPORT).get());input.setTag(payload);var grid=frame();grid.setItem(0,input);var converted=h.getLevel().getRecipeManager().getRecipeFor(RecipeType.CRAFTING,grid,h.getLevel()).orElseThrow().assemble(grid,h.getLevel().registryAccess());h.assertTrue(converted.is(AWCells.PARTS.get(MachineKind.FLUID_IMPORT).get())&&payload.equals(converted.getTag()),"Block-to-part conversion preserves NBT");grid.setItem(1,new ItemStack(AWCells.BLOCK_ITEMS.get(MachineKind.IMPORT).get()));h.assertTrue(h.getLevel().getRecipeManager().getRecipeFor(RecipeType.CRAFTING,grid,h.getLevel()).isEmpty(),"Combined assembly rejects configured machine rather than deleting its state");h.succeed();
    }
    @GameTest(template="empty") public static void equalDistributionTagFiltersAndCommands(GameTestHelper h){
        var stack=new ItemStack(AWCells.cell(CellFamily.HD_ITEM,CellTier.K1).get());var item=(TieredCellItem)stack.getItem();item.getUpgrades(stack).setItemDirect(0,new ItemStack(AWCells.UPGRADES.get("equal_distribution_card_2x").get()));var cell=CellHandler.open(stack,null);long first=cell.insert(IRON,Long.MAX_VALUE,Actionable.MODULATE,SOURCE);long second=cell.insert(AEItemKey.of(Items.GOLD_INGOT),Long.MAX_VALUE,Actionable.MODULATE,SOURCE);h.assertTrue(first>0&&first==second&&cell.insert(AEItemKey.of(Items.DIRT),1,Actionable.MODULATE,SOURCE)==0,"Equal per-type quota and type limit");
        var tagged=new ItemStack(AWCells.cell(CellFamily.HD_ITEM,CellTier.K1).get());item.getUpgrades(tagged).setItemDirect(0,new ItemStack(AWCells.UPGRADES.get("tag_card").get()));tagged.getOrCreateTag().putString("filterTag","forge:ingots/iron");var filter=CellHandler.open(tagged,null);h.assertTrue(filter.insert(IRON,1,Actionable.SIMULATE,SOURCE)==1&&filter.insert(AEItemKey.of(Items.DIRT),1,Actionable.SIMULATE,SOURCE)==0,"Namespaced tag filter");
        var player=net.minecraftforge.common.util.FakePlayerFactory.get(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"P3Commands"));player.getInventory().selected=0;player.getInventory().setItem(0,tagged);var source=player.createCommandSourceStack().withPermission(2).withSuppressedOutput();h.assertTrue(h.getLevel().getServer().getCommands().performPrefixedCommand(source,"fillcell item minecraft:iron_ingot 4294967296")==1&&count(CellHandler.open(tagged,null),IRON)==4294967296L,"Brigadier fill accepts long quantities");h.assertTrue(h.getLevel().getServer().getCommands().performPrefixedCommand(source,"inspectslot 0")==1,"Inspect command");h.succeed();
    }


    @GameTest(template="empty") public static void compressionCardsAndTagUnification(GameTestHelper h){
        var stack=new ItemStack(AWCells.cell(CellFamily.COMPACTING,CellTier.K1).get());var item=(TieredCellItem)stack.getItem();item.getConfigInventory(stack).setStack(0,new GenericStack(AEItemKey.of(Items.IRON_NUGGET),1));
        var cell=(CompactingCellState)CellHandler.open(stack,null);h.assertTrue(cell.insert(AEItemKey.of(Items.IRON_BLOCK),1,Actionable.SIMULATE,SOURCE)==0,"Default one upper tier");item.getUpgrades(stack).setItemDirect(0,new ItemStack(AWCells.UPGRADES.get("compression_tier_card_3x").get()));cell=(CompactingCellState)CellHandler.open(stack,null);h.assertTrue(cell.insert(AEItemKey.of(Items.IRON_BLOCK),2,Actionable.MODULATE,SOURCE)==2,"Two compression tiers are active");h.assertTrue(cell.extract(AEItemKey.of(Items.IRON_NUGGET),162,Actionable.MODULATE,SOURCE)==162,"Cross-tier exact extraction");
        item.getConfigInventory(stack).setStack(0,new GenericStack(AEItemKey.of(Items.IRON_BLOCK),1));item.getUpgrades(stack).setItemDirect(0,new ItemStack(AWCells.UPGRADES.get("decompression_tier_card_3x").get()));cell=(CompactingCellState)CellHandler.open(stack,null);h.assertTrue(cell.insert(AEItemKey.of(Items.IRON_NUGGET),82,Actionable.MODULATE,SOURCE)==82,"Two lower tiers are active");item.getUpgrades(stack).setItemDirect(0,ItemStack.EMPTY);cell=(CompactingCellState)CellHandler.open(stack,null);h.assertTrue(cell.extract(AEItemKey.of(Items.IRON_BLOCK),1,Actionable.MODULATE,SOURCE)==1&&cell.extract(AEItemKey.of(Items.IRON_NUGGET),1,Actionable.MODULATE,SOURCE)==1,"Downgrade retains indivisible remainder");
        var tagged=new ItemStack(AWCells.cell(CellFamily.COMPACTING,CellTier.K1).get());item.getConfigInventory(tagged).setStack(0,new GenericStack(IRON,1));var variant=new ItemStack(Items.IRON_INGOT);variant.setHoverName(net.minecraft.network.chat.Component.literal("Equivalent ingot"));h.assertTrue(CellHandler.open(tagged,null).insert(AEItemKey.of(variant),13,Actionable.SIMULATE,SOURCE)==0,"No implicit conversion");item.getUpgrades(tagged).setItemDirect(0,new ItemStack(AWCells.UPGRADES.get("tag_card").get()));tagged.getOrCreateTag().putString("filterTag","forge:ingots/iron");var unified=CellHandler.open(tagged,null);h.assertTrue(unified.insert(AEItemKey.of(variant),13,Actionable.MODULATE,SOURCE)==13&&unified.extract(IRON,13,Actionable.MODULATE,SOURCE)==13,"Explicit Tag card unifies to configured chain");h.succeed();
    }
    @GameTest(template="empty",timeoutTicks=150) public static void automaticPullRespectsKeepAndQuantity(GameTestHelper h){
        network(h,MachineKind.IMPORT);h.setBlock(0,1,1,net.minecraft.world.level.block.Blocks.CHEST);h.runAfterDelay(40,()->{var logic=(InterfaceLogic)machine(h).cellsLogic();var external=(net.minecraft.world.level.block.entity.ChestBlockEntity)h.getBlockEntity(new BlockPos(0,1,1));external.setItem(0,new ItemStack(Items.IRON_INGOT,20));logic.keepQuantity=5;logic.transferQuantity=10;logic.upgrades.setItemDirect(0,new ItemStack(AWCells.UPGRADES.get("pull_card").get()));logic.tick();h.assertTrue(external.getItem(0).getCount()==10&&logic.ports.get(0).amounts[0]==10,"Pull honors transfer amount");logic.tick();h.assertTrue(external.getItem(0).getCount()==10&&count(machine(h).getMainNode().getGrid().getStorageService().getInventory(),IRON)==10,"Pulled contents reach ME; same tick does not pull twice");h.runAfterDelay(2,()->{logic.tick();h.assertTrue(external.getItem(0).getCount()==5,"Keep floor remains in external chest");h.succeed();});});
    }
