    @GameTest(template="empty",timeoutTicks=240) public static void parallelProxyPriorityFuzzyAndCycle(GameTestHelper h){
        h.setBlock(1,1,1,AEBlocks.DRIVE.block());h.setBlock(1,0,1,AEBlocks.CREATIVE_ENERGY_CELL.block());h.setBlock(4,0,1,AEBlocks.CREATIVE_ENERGY_CELL.block());
        var drive=(DriveBlockEntity)h.getBlockEntity(new BlockPos(1,1,1));drive.getInternalInventory().setItemDirect(0,AEItems.ITEM_CELL_64K.stack());
        var backs=new CellsPart[2];var fronts=new CellsPart[2];var reverse=new CellsPart[2];
        for(int i=0;i<2;i++){backs[i]=PartHelper.setPart(h.getLevel(),h.absolutePos(new BlockPos(2,1,1+i*2)),Direction.EAST,h.makeMockPlayer(),AWCells.PARTS.get(MachineKind.PROXY_BACK).get());fronts[i]=PartHelper.setPart(h.getLevel(),h.absolutePos(new BlockPos(3,1,1+i*2)),Direction.WEST,h.makeMockPlayer(),AWCells.PARTS.get(MachineKind.PROXY_FRONT).get());}
        h.runAfterDelay(30,()->{var power=(appeng.me.helpers.IGridConnectedBlockEntity)h.getBlockEntity(new BlockPos(4,0,1));for(int i=0;i<2;i++){if(backs[i].getGridNode().getGrid()!=drive.getMainNode().getGrid())GridHelper.createConnection(backs[i].getGridNode(),drive.getMainNode().getNode());if(fronts[i].getGridNode().getGrid()!=power.getMainNode().getGrid())GridHelper.createConnection(fronts[i].getGridNode(),power.getMainNode().getNode());}});
        h.runAfterDelay(85,()->{var a=(ProxyLogic)fronts[0].logic;var b=(ProxyLogic)fronts[1].logic;var origin=drive.getMainNode().getGrid().getStorageService().getInventory();origin.insert(IRON,120,Actionable.MODULATE,SOURCE);a.priority=10;b.priority=20;
            h.assertTrue(count(a.storageView(),IRON)==0&&count(b.storageView(),IRON)==120,"Only higher priority parallel proxy lists physical inventory");a.priority=30;h.assertTrue(count(a.storageView(),IRON)==120&&count(b.storageView(),IRON)==0,"Priority handover has no double counting");
            var named=new ItemStack(Items.IRON_INGOT);named.setHoverName(net.minecraft.network.chat.Component.literal("Named variant"));var key=AEItemKey.of(named);origin.insert(key,9,Actionable.MODULATE,SOURCE);a.filters.setStack(0,new GenericStack(IRON,1));h.assertTrue(count(a.storageView(),key)==0,"Exact filter rejects NBT variant");a.upgrades.setItemDirect(0,AEItems.FUZZY_CARD.stack());h.assertTrue(count(a.storageView(),key)==9,"Fuzzy card exposes matching variant");a.items=false;h.assertTrue(count(a.storageView(),IRON)==0,"Channel disable applies to proxy view");a.items=true;
            reverse[0]=PartHelper.setPart(h.getLevel(),h.absolutePos(new BlockPos(2,1,2)),Direction.EAST,h.makeMockPlayer(),AWCells.PARTS.get(MachineKind.PROXY_FRONT).get());reverse[1]=PartHelper.setPart(h.getLevel(),h.absolutePos(new BlockPos(3,1,2)),Direction.WEST,h.makeMockPlayer(),AWCells.PARTS.get(MachineKind.PROXY_BACK).get());
        });
        h.runAfterDelay(115,()->{GridHelper.createConnection(reverse[0].getGridNode(),backs[0].getGridNode());GridHelper.createConnection(reverse[1].getGridNode(),fronts[0].getGridNode());});
        h.runAfterDelay(175,()->{for(var part:List.of(fronts[0],fronts[1],reverse[0])){var proxy=(ProxyLogic)part.logic;h.assertTrue(proxy.guardStatus().equals("CYCLE")&&count(proxy.storageView(),IRON)==0,"Real two-network cycle closes all views: "+proxy.guardStatus());}h.succeed();});
    }

    @GameTest(template="empty") public static void proxyTickBoundsAndConfiguredUpgradeCapacity(GameTestHelper h){
        var config=com.mpp.aedialsworks.common.config.AWConfigs.SERVER.cells.general;
        int oldMin=config.subnetProxyMinTickRate.get(),oldMax=config.subnetProxyMaxTickRate.get(),oldSlots=config.subnetProxyUpgradeSlots.get(),oldCellSlots=config.hdItemCellUpgradeSlots.get();
        try{
            config.subnetProxyMinTickRate.set(37);config.subnetProxyMaxTickRate.set(11);config.subnetProxyUpgradeSlots.set(24);config.hdItemCellUpgradeSlots.set(16);
            var part=AWCells.PARTS.get(MachineKind.PROXY_FRONT).get().createPart();var proxy=(ProxyLogic)part.logic;var request=proxy.getTickingRequest(null);
            h.assertTrue(request.minTickRate()==37&&request.maxTickRate()==37&&request.initialTickRate()==37,"Inverted tick bounds are normalized");
            h.assertTrue(proxy.upgrades.size()==24,"Configured proxy upgrade slots");
            config.subnetProxyMaxTickRate.set(120);request=proxy.getTickingRequest(null);h.assertTrue(request.maxTickRate()==120,"Configured maximum tick interval is applied");
            var item=AWCells.cell(CellFamily.HD_ITEM,CellTier.K1).get();h.assertTrue(item.getUpgrades(new ItemStack(item)).size()==16,"Configured cell upgrade slots");
        }finally{config.subnetProxyMinTickRate.set(oldMin);config.subnetProxyMaxTickRate.set(oldMax);config.subnetProxyUpgradeSlots.set(oldSlots);config.hdItemCellUpgradeSlots.set(oldCellSlots);}
        h.succeed();
    }

